"""Test script to verify the __post_configure__ hook works correctly."""

from zookeeper.core.component import component, configure
from zookeeper.core.field import Field

# Test 1: Basic hook functionality
@component
class ComponentWithHook:
    x: int = Field(5)

    def __post_configure__(self):
        self.post_configure_called = True
        assert self.x == 10, f"Expected x=10, got x={self.x}"

# Test 2: Hook called after configuration
c = ComponentWithHook()
configure(c, {"x": 10})
assert hasattr(c, "post_configure_called"), "Hook was not called"
assert c.post_configure_called, "Hook method was not executed"

print("Test 1 passed: Basic hook functionality")

# Test 3: Hook validation (non-callable)
try:
    @component
    class BadComponent1:
        x = 123  # Not a method
        __post_configure__ = x
    assert False, "Should have raised TypeError"
except TypeError as e:
    assert "must be a method" in str(e), f"Wrong error: {e}"
    print("Test 3 passed: Non-callable hook detected")

# Test 4: Hook validation (wrong signature)
try:
    @component
    class BadComponent2:
        def __post_configure__(self, extra_arg):
            pass
    assert False, "Should have raised TypeError"
except TypeError as e:
    assert "must take no arguments" in str(e), f"Wrong error: {e}"
    print("Test 4 passed: Incorrect hook signature detected")

# Test 5: Hook called only once
call_count = 0
@component
class SingleCallComponent:
    def __post_configure__(self):
        global call_count
        call_count += 1

c = SingleCallComponent()
configure(c, {})
assert call_count == 1, f"Expected 1 call, got {call_count}"
print("Test 5 passed: Hook called once")

# Test 6: Inheritance works
@component
class BaseComponent:
    def __post_configure__(self):
        self.base_called = True

@component
class ChildComponent(BaseComponent):
    def __post_configure__(self):
        super().__post_configure__()
        self.child_called = True

c = ChildComponent()
configure(c, {})
assert hasattr(c, "base_called") and hasattr(c, "child_called"), "Inheritance broken"
assert c.base_called and c.child_called, "Inheritance not working"
print("Test 6 passed: Hook inheritance works")

print("\nAll tests passed!")
EOF
