#!/usr/bin/env python3
"""Test script for the __post_configure__ hook."""

from zookeeper.core.component import component, configure
from zookeeper.core.field import Field


@component
class TestComponent:
    x: int = Field()
    y: str = Field("default")

    def __post_configure__(self):
        print(f"__post_configure__ called with x={self.x}, y={self.y}")
        # Simple validation
        if self.x < 0:
            raise ValueError("x must be non-negative")


def test_basic_hook():
    """Test that __post_configure__ is called after configuration."""
    c = TestComponent()
    configure(c, {"x": 5, "y": "test"})
    assert c.x == 5
    assert c.y == "test"
    print("✓ Basic hook test passed")


def test_hook_validation():
    """Test that __post_configure__ can raise validation errors."""
    c = TestComponent()
    try:
        configure(c, {"x": -1})
        assert False, "Should have raised ValueError"
    except ValueError as e:
        assert "x must be non-negative" in str(e)
        print("✓ Hook validation test passed")


def test_no_hook():
    """Test that components without __post_configure__ work normally."""
    @component
    class NoHookComponent:
        z: int = Field()

    c = NoHookComponent()
    configure(c, {"z": 10})
    assert c.z == 10
    print("✓ No hook test passed")


def test_invalid_hook_signature():
    """Test that invalid __post_configure__ signature raises TypeError."""
    @component
    class InvalidHookComponent:
        a: int = Field()

        def __post_configure__(self, extra_arg):  # Invalid signature
            pass

    try:
        c = InvalidHookComponent()
        configure(c, {"a": 5})
        assert False, "Should have raised TypeError"
    except TypeError as e:
        assert "must take no arguments except `self`" in str(e)
        print("✓ Invalid hook signature test passed")


def test_non_callable_hook():
    """Test that non-callable __post_configure__ raises TypeError."""
    @component
    class NonCallableHookComponent:
        b: int = Field()

        __post_configure__ = "not a method"  # Not callable

    try:
        c = NonCallableHookComponent()
        configure(c, {"b": 5})
        assert False, "Should have raised TypeError"
    except TypeError as e:
        assert "must be a method" in str(e)
        print("✓ Non-callable hook test passed")


if __name__ == "__main__":
    test_basic_hook()
    test_hook_validation()
    test_no_hook()
    test_invalid_hook_signature()
    test_non_callable_hook()
    print("\n✓ All tests passed!")
EOF
